/* Œconomia — Entraînement : thème « Finance » (24 exercices, trois niveaux). */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");

  X.theme({ id: "finance", nom: "Finance",
    intro: "À quoi servent les banques et les marchés financiers, comment évaluer un placement, et pourquoi la finance connaît-elle des crises ? Ces exercices vous entraînent à calculer des intérêts, des rendements et des valeurs actuelles, à comprendre le risque et l’effet de levier, et à discuter de la régulation.",
    notions: ["instabilite-financiere", "preteur-dernier-ressort", "alea-moral", "aversion-pertes", "asymetrie-information", "preference-liquidite"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "fi1-action-obligation", theme: "finance", niveau: 1, type: "qcm", notion: "preference-liquidite",
    titre: "Action ou obligation ?", competence: "Distinguer les deux grands titres financiers.",
    enonce: P("Quelle phrase décrit correctement la différence entre une action et une obligation ?"),
    options: ["Une action est un prêt à une entreprise ; une obligation est une part de propriété, qui donne droit à des dividendes.", "Une action est une part de propriété qui donne droit aux bénéfices ; une obligation est un prêt qui rapporte un intérêt.", "Une action et une obligation rapportent toujours le même revenu, car toutes deux sont émises par des entreprises.", "Seuls les États émettent des actions, tandis que les entreprises émettent uniquement des obligations."], c: 1, pourquoi: ["C’est l’inverse : l’action est une part de propriété, l’obligation un prêt.", null, "Le dividende d’une action varie avec les bénéfices et peut être nul ; l’intérêt d’une obligation est fixé à l’avance.", "Les États émettent des obligations, pas des actions. Les entreprises, elles, peuvent émettre les deux."],
    explication: P("L’<b>action</b> fait de son détenteur un copropriétaire de l’entreprise : il touche des dividendes si l’entreprise fait des bénéfices et décide d’en distribuer, et son prix varie avec les perspectives de l’entreprise. Le risque et le rendement espéré sont élevés.", "L’<b>obligation</b> est une créance : l’emprunteur, entreprise ou État, verse un intérêt (coupon) et rembourse le capital à l’échéance. Elle est en général moins risquée, sauf si l’emprunteur fait faillite.") },

  { id: "fi1-composes", theme: "finance", niveau: 1, type: "calcul",
    titre: "Les intérêts composés", competence: "Calculer la valeur future d’un placement.",
    gen: () => ({ c: rnd(2, 20) * 1000, i: pick([1, 2, 3, 4, 5, 6]), n: pick([5, 10, 20, 30]) }),
    enonce: (p) => P(`Vous placez <b>${fmt(p.c)} francs</b> à un taux de <b>${p.i} %</b> par an, et vous réinvestissez chaque année les intérêts.`, `Quelle sera la valeur du placement dans <b>${p.n} ans</b> ? Arrondissez au franc.`),
    champs: [{ label: "Valeur future", unite: "fr.", tol: 1 }],
    reponses: (p) => [Math.round(p.c * Math.pow(1 + p.i / 100, p.n))],
    indice: "Valeur future = capital × (1 + taux) puissance nombre d’années.",
    correction: (p) => { const v = p.c * Math.pow(1 + p.i / 100, p.n); return P(`Valeur future = ${fmt(p.c)} × ${fmt(1 + p.i / 100, 2)}<sup>${p.n}</sup>`, `≈ <b>${fmt(Math.round(v))} francs</b>.`, `Avec des intérêts simples (non réinvestis), on aurait obtenu ${fmt(p.c * (1 + p.n * p.i / 100))} francs. La différence, ${fmt(Math.round(v - p.c * (1 + p.n * p.i / 100)))} francs, vient des « intérêts sur les intérêts » : c’est l’effet des intérêts composés, d’autant plus fort que la durée est longue.`); } },

  { id: "fi1-rendement", theme: "finance", niveau: 1, type: "calcul",
    titre: "Le rendement d’une action", competence: "Calculer le rendement total d’un placement.",
    gen: () => { const p0 = rnd(40, 120); return { p0, p1: Math.round(p0 * (1 + rnd(-20, 25) / 100)), d: Math.max(1, Math.round(p0 * rnd(2, 4) / 100)) }; },
    enonce: (p) => P(`Vous achetez une action <b>${p.p0} francs</b>. Pendant l’année, elle vous verse un dividende de <b>${p.d} francs</b>. Un an plus tard, vous la revendez <b>${p.p1} francs</b>.`, "Quel est votre rendement total sur l’année ? Arrondissez à une décimale (signe moins en cas de perte)."),
    champs: [{ label: "Rendement", unite: "%", tol: 0.1 }],
    reponses: (p) => [Math.round(((p.p1 - p.p0 + p.d) / p.p0) * 1000) / 10],
    indice: "Rendement = (prix de vente − prix d’achat + dividende) ÷ prix d’achat × 100.",
    correction: (p) => { const r = (p.p1 - p.p0 + p.d) / p.p0 * 100; return P(`Gain = (${p.p1} − ${p.p0}) + ${p.d} = ${p.p1 - p.p0 + p.d} francs.`, `Rendement = ${p.p1 - p.p0 + p.d} ÷ ${p.p0} × 100 ≈ <b>${fmt(r, 1)} %</b>.`, "Le rendement d’une action combine le dividende et la variation de prix (plus-value ou moins-value). Cette variation peut être forte d’une année à l’autre : c’est le prix du rendement moyen plus élevé des actions sur longue période."); } },

  { id: "fi1-vf-bases", theme: "finance", niveau: 1, type: "vf", notion: "preference-liquidite",
    titre: "Finance : les bases", competence: "Connaître quelques principes fondamentaux.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["En général, un placement qui promet un rendement plus élevé est aussi plus risqué.", true, "C’est la relation entre risque et rendement : pour accepter plus de risque, les investisseurs exigent un rendement espéré plus élevé. Un placement qui promet beaucoup sans risque doit éveiller la méfiance."],
      ["En Suisse, les dépôts bancaires sont garantis jusqu’à 100 000 francs par client et par banque en cas de faillite.", true, "C’est la garantie des dépôts, organisée par les banques elles-mêmes (esisuisse) et prévue par la loi."],
      ["Quand les taux d’intérêt montent, le prix des obligations déjà émises augmente.", false, "Il <b>baisse</b> : les nouvelles obligations rapportent plus, les anciennes, à coupon plus faible, deviennent moins attractives et leur prix diminue."],
      ["Répartir son épargne entre de nombreux placements différents réduit le risque.", true, "C’est la <b>diversification</b> : les pertes des uns sont en partie compensées par les gains des autres."]
    ] },

  { id: "fi1-diversification", theme: "finance", niveau: 1, type: "qcm", notion: "aversion-pertes",
    titre: "Ne pas mettre tous ses œufs dans le même panier", competence: "Comprendre l’intérêt de la diversification.",
    enonce: P("Marie a 20 000 francs d’épargne. Elle hésite entre acheter des actions d’une seule entreprise, celle où elle travaille, ou un fonds qui détient des actions de plusieurs centaines d’entreprises. Que conseille la théorie financière ?"),
    options: ["Les actions de son entreprise, car elle la connaît bien, ce qui réduit le risque de mauvaise surprise.", "Le fonds, car le risque propre à chaque entreprise s’y compense en partie et son épargne ne dépend plus de son employeur.", "Les actions de son entreprise, car une action bien choisie rapporte plus qu’un fonds, qui fait la moyenne.", "Peu importe, car à montant égal le risque est le même dans les deux cas."], c: 1, pourquoi: ["Bien connaître son entreprise ne supprime pas son risque, et l’épargne de Marie dépendrait de son employeur : si l’entreprise va mal, elle perd les deux.", null, "Une action peut rapporter plus qu’un fonds, mais aussi perdre toute sa valeur. Personne ne sait d’avance laquelle sera bien choisie.", "Le risque n’est pas le même : un fonds de centaines d’entreprises dépend beaucoup moins du sort d’une seule."],
    explication: P("La <b>diversification</b> réduit le risque spécifique de chaque entreprise sans réduire beaucoup le rendement espéré. Investir toute son épargne chez son employeur cumule deux risques sur le même événement. Lors de la faillite d’Enron en 2001, de nombreux salariés ont ainsi perdu leur emploi et leur épargne-retraite.", "Harry Markowitz a reçu le prix Nobel en 1990 pour avoir formalisé cette idée.") },

  { id: "fi1-banque", theme: "finance", niveau: 1, type: "qcm", notion: "preteur-dernier-ressort",
    titre: "Le métier d’une banque", competence: "Comprendre le métier de base d’une banque et le risque qu’il crée.",
    enonce: P("Une banque cantonale reçoit des dépôts que ses clients peuvent retirer à tout moment, et accorde des hypothèques à taux fixe sur dix ans. Quel risque cette activité crée-t-elle ?"),
    options: ["Un risque de change, parce que la banque prête et emprunte dans des monnaies différentes.", "Un risque de panique, si de nombreux déposants veulent retirer leur argent en même temps.", "Aucun risque, parce que la banque garde en réserve tous les dépôts qu’elle reçoit.", "Un risque d’inflation, parce que la banque émet de la monnaie fiduciaire."], c: 1, pourquoi: ["Les dépôts et les hypothèques sont ici tous en francs : il n’y a pas de risque de change.", null, "Une banque ne garde en réserve qu’une petite part des dépôts. Le reste est prêté à long terme, alors que les dépôts sont disponibles à court terme, ce qui crée un vrai risque.", "Les billets sont émis par la BNS, pas par une banque cantonale."],
    explication: P("La banque <b>transforme</b> des dépôts disponibles à court terme en prêts à long terme. C’est très utile : les déposants gardent leur argent disponible, et les emprunteurs peuvent financer des projets longs. Mais si tous les déposants veulent retirer leur argent au même moment, la banque ne peut pas les rembourser immédiatement : c’est la <b>panique bancaire</b>.", "Douglas Diamond et Philip Dybvig ont reçu le Nobel en 2022 pour l’analyse de ce mécanisme. La garantie des dépôts et la banque centrale, comme prêteur en dernier ressort, permettent de l’éviter.") },

  { id: "fi1-piliers", theme: "finance", niveau: 1, type: "qcm",
    titre: "Les trois piliers de la prévoyance suisse", competence: "Connaître l’organisation des retraites en Suisse.",
    enonce: P("Le système suisse de prévoyance vieillesse repose sur trois piliers. Comment le deuxième pilier fonctionne-t-il ?"),
    options: ["C’est l’AVS, financée par répartition : les cotisations des actifs paient les rentes des retraités.", "C’est la prévoyance professionnelle : salariés et employeurs cotisent à une caisse de pension qui place l’argent.", "C’est l’épargne individuelle volontaire, encouragée fiscalement, comme le pilier 3a.", "C’est l’aide sociale, versée aux personnes sans ressources suffisantes à la retraite."], c: 1, pourquoi: ["C’est le premier pilier, l’AVS.", null, "C’est le troisième pilier.", "L’aide sociale ne fait pas partie des trois piliers : elle intervient en dernier recours."],
    explication: P("Le <b>premier pilier</b> (AVS) fonctionne par <b>répartition</b> : les cotisations d’aujourd’hui financent les rentes d’aujourd’hui. Le <b>deuxième pilier</b> (prévoyance professionnelle, obligatoire pour la plupart des salariés) fonctionne par <b>capitalisation</b> : chacun accumule un capital placé par sa caisse de pension. Le <b>troisième pilier</b> est l’épargne individuelle, encouragée fiscalement (pilier 3a).", "Les caisses de pension gèrent plus de 1 000 milliards de francs, ce qui fait d’elles de grands investisseurs sur les marchés financiers.") },

  { id: "fi1-placements", theme: "finance", niveau: 1, type: "document", notion: "aversion-pertes",
    titre: "Choisir un placement selon son horizon", competence: "Relier risque, rendement et horizon de placement.",
    enonce: P("Caractéristiques historiques approximatives de trois types de placements sur longue période (valeurs indicatives) :") +
      `<table><thead><tr><th>Placement</th><th>Rendement annuel moyen</th><th>Pire année observée</th></tr></thead><tbody><tr><td>Compte d’épargne</td><td>environ 0,5 %</td><td>0 %</td></tr><tr><td>Obligations de la Confédération</td><td>environ 2 %</td><td>environ −10 %</td></tr><tr><td>Actions suisses (fonds diversifié)</td><td>environ 6 %</td><td>environ −35 %</td></tr></tbody></table><p class="ex-source">Valeurs indicatives et arrondies, à but pédagogique : elles changent selon la période observée.</p>` +
      P("Quel conseil est le plus raisonnable ?"),
    options: ["Tout placer en actions, quel que soit l’horizon, puisque leur rendement moyen est le plus élevé.", "Garder sur un compte l’argent nécessaire dans six mois, et placer en actions diversifiées une partie de l’épargne à vingt ans.", "Tout laisser sur le compte d’épargne, même pour vingt ans, puisque c’est le seul placement qui ne baisse pas.", "Choisir les obligations pour l’argent nécessaire dans six mois, car elles rapportent plus que le compte sans pouvoir baisser."], c: 1, pourquoi: ["Les actions rapportent davantage en moyenne, mais une perte de 35 % en un an peut obliger à vendre au pire moment si l’on a besoin de l’argent bientôt.", null, "Sur vingt ans, un rendement de 0,5 % par an rapporte bien moins que les autres placements, dont les mauvaises années ont été rattrapées sur longue période.", "Le tableau montre une pire année d’environ −10 % : le prix des obligations baisse quand les taux d’intérêt montent."],
    explication: P("Le bon choix dépend de l’<b>horizon</b> et de la capacité à supporter des pertes. À court terme, une baisse de 35 % peut obliger à vendre au pire moment ; à long terme, les actions ont historiquement rapporté davantage, et les mauvaises années ont été compensées.", "Les obligations ne sont pas sans risque : leur prix baisse quand les taux montent, comme en 2022. Les rendements passés ne garantissent pas les rendements futurs.") },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "fi2-actualisation", theme: "finance", niveau: 2, type: "calcul",
    titre: "La valeur actuelle", competence: "Actualiser une somme future.",
    gen: () => ({ f: rnd(5, 50) * 1000, r: pick([1, 2, 3, 4, 5]), n: pick([2, 5, 10, 20]) }),
    enonce: (p) => P(`Quelqu’un vous promet <b>${fmt(p.f)} francs</b> dans <b>${p.n} ans</b>. Vous pourriez placer votre argent sans risque à <b>${p.r} %</b> par an.`, "Combien vaut cette promesse aujourd’hui ? Arrondissez au franc."),
    champs: [{ label: "Valeur actuelle", unite: "fr.", tol: 1 }],
    reponses: (p) => [Math.round(p.f / Math.pow(1 + p.r / 100, p.n))],
    indice: "Valeur actuelle = somme future ÷ (1 + taux) puissance nombre d’années.",
    correction: (p) => { const v = p.f / Math.pow(1 + p.r / 100, p.n); return P(`Valeur actuelle = ${fmt(p.f)} ÷ ${fmt(1 + p.r / 100, 2)}<sup>${p.n}</sup>`, `≈ <b>${fmt(Math.round(v))} francs</b>.`, `C’est la somme qu’il faudrait placer aujourd’hui à ${p.r} % pour obtenir ${fmt(p.f)} francs dans ${p.n} ans.`, "L’actualisation est au cœur de la finance : la valeur d’une action, d’une obligation ou d’un investissement est la valeur actuelle des revenus futurs qu’il rapportera. Plus les taux d’intérêt sont élevés, plus cette valeur est faible."); } },

  { id: "fi2-obligation", theme: "finance", niveau: 2, type: "calcul", notion: "preference-liquidite",
    titre: "Taux d’intérêt et prix d’une obligation", competence: "Calculer l’effet d’une hausse des taux sur le prix d’une obligation.",
    gen: () => ({ c: pick([20, 25, 30, 40, 50]), r0: pick([1, 2, 2.5]), r1: pick([3, 4, 5]) }),
    enonce: (p) => P(`Une obligation perpétuelle (jamais remboursée) verse un coupon de <b>${p.c} francs</b> par an. Son prix est égal à la valeur actuelle de tous ses coupons futurs, soit <b>coupon ÷ taux d’intérêt du marché</b>.`, `Calculez son prix quand le taux du marché est de <b>${fmt(p.r0)} %</b>, puis quand il passe à <b>${fmt(p.r1)} %</b>. Arrondissez au franc.`),
    champs: [{ label: "Prix à " + "taux bas", unite: "fr.", tol: 0.5 }, { label: "Prix à taux élevé", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [Math.round((p.c / (p.r0 / 100)) * 100) / 100, Math.round((p.c / (p.r1 / 100)) * 100) / 100],
    indice: "Exprimez le taux en fraction : 2 % = 0,02.",
    correction: (p) => { const a = p.c / (p.r0 / 100), b = p.c / (p.r1 / 100); return P(`À ${fmt(p.r0)} % : ${p.c} ÷ ${fmt(p.r0 / 100, 3)}. À ${fmt(p.r1)} % : ${p.c} ÷ ${fmt(p.r1 / 100, 3)}.`, `Prix à ${fmt(p.r0)} % = <b>${fmt(a)} francs</b>. Prix à ${fmt(p.r1)} % = <b>${fmt(b)} francs</b>.`, `Le prix baisse de ${fmt(100 * (1 - b / a), 0)} % : quand les taux montent, les anciennes obligations, qui rapportent moins que les nouvelles, perdent de la valeur.`, "C’est ce qui s’est passé en 2022, quand les banques centrales ont relevé leurs taux : de nombreux détenteurs d’obligations, dont des caisses de pension et des banques comme la Silicon Valley Bank aux États-Unis, ont subi de lourdes pertes."); } },

  { id: "fi2-levier", theme: "finance", niveau: 2, type: "calcul", notion: "instabilite-financiere",
    titre: "L’effet de levier", competence: "Calculer l’effet d’une perte sur les fonds propres d’une banque.",
    gen: () => ({ a: pick([200, 500, 1000]), fp: pick([3, 4, 5, 8, 10]), perte: pick([1, 2, 3, 5]) }),
    enonce: (p) => P(`Une banque détient <b>${p.a} milliards</b> d’actifs (crédits, titres). Elle les finance avec <b>${p.fp} %</b> de fonds propres (l’argent de ses actionnaires) et le reste par des dettes (dépôts, emprunts).`, `Ses actifs perdent <b>${p.perte} %</b> de leur valeur. Calculez le montant de ses fonds propres avant la perte, puis la perte en % de ses fonds propres. Arrondissez à une décimale.`),
    champs: [{ label: "Fonds propres", unite: "milliards", tol: 0.05 }, { label: "Perte sur fonds propres", unite: "%", tol: 0.5 }],
    reponses: (p) => [p.a * p.fp / 100, Math.round((p.perte / p.fp) * 1000) / 10],
    indice: "La perte en francs est supportée d’abord par les fonds propres.",
    correction: (p) => { const fp = p.a * p.fp / 100, pe = p.a * p.perte / 100; return P(`Fonds propres = ${fmt(p.fp)} % × ${p.a} = <b>${fmt(fp)} milliards</b>. Perte = ${fmt(p.perte)} % × ${p.a} = ${fmt(pe)} milliards.`, `Perte en % des fonds propres = ${fmt(pe)} ÷ ${fmt(fp)} × 100 = <b>${fmt(100 * p.perte / p.fp, 1)} %</b>.`, p.perte >= p.fp ? "Les fonds propres sont entièrement perdus : la banque est en faillite, et ses créanciers ne seront pas tous remboursés." : `Avec peu de fonds propres, une petite perte sur les actifs devient une grosse perte pour les actionnaires : c’est l’<b>effet de levier</b>. C’est pourquoi les régulateurs exigent davantage de fonds propres depuis 2008.`); } },

  { id: "fi2-concours", theme: "finance", niveau: 2, type: "qcm", notion: "instabilite-financiere",
    titre: "Le concours de beauté de Keynes", competence: "Comprendre une analyse classique de la spéculation.",
    enonce: P("Au chapitre 12 de la Théorie générale, Keynes compare la Bourse à un concours de beauté organisé par un journal, où il faut désigner non le plus beau visage, mais celui que la majorité des participants choisira. Que veut-il montrer ?"),
    options: ["Que les investisseurs finissent par repérer les meilleures entreprises, comme un jury repère le plus beau visage.", "Que les investisseurs cherchent à deviner l’opinion des autres plutôt que la valeur des entreprises, au risque d’en écarter les prix.", "Que les cours dépendent surtout de l’image des entreprises dans les journaux, donc de leur publicité.", "Que la Bourse est un jeu de hasard, où le gain ne dépend d’aucun raisonnement."], c: 1, pourquoi: ["Keynes montre l’inverse : en cherchant à deviner l’opinion des autres, les investisseurs peuvent s’écarter de la valeur réelle des entreprises.", null, "Keynes ne parle pas de publicité. Le journal n’est qu’une image, ce qui compte est que chacun cherche à prévoir le choix des autres.", "Le concours demande au contraire un raisonnement poussé sur ce que les autres pensent. Le problème est que ce raisonnement se détache de la valeur des entreprises."],
    explication: P("Pour Keynes, l’investisseur professionnel cherche à anticiper l’opinion moyenne, et même ce que l’opinion moyenne pense de l’opinion moyenne. Les prix reposent alors sur des <b>conventions</b> fragiles, qui peuvent basculer brutalement.", "Il en conclut : « Quand le développement du capital d’un pays devient un sous-produit des activités d’un casino, le travail risque d’être mal fait. »") },

  { id: "fi2-vf-efficience", theme: "finance", niveau: 2, type: "vf", notion: "aversion-pertes",
    titre: "Marchés efficients et finance comportementale", competence: "Confronter deux visions des marchés financiers.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["La plupart des fonds gérés activement font mieux que leur indice de référence sur longue période, une fois les frais déduits.", false, "C’est l’inverse : la majorité fait <b>moins bien</b>, ce qui soutient l’hypothèse d’efficience et le succès des fonds indiciels à bas coût."],
      ["Selon l’hypothèse des marchés efficients d’Eugene Fama, les prix reflètent toute l’information disponible.", true, "Il est alors impossible de battre durablement le marché, sauf par chance ou par information privilégiée."],
      ["Robert Shiller a montré que les cours des actions varient beaucoup plus que ne le justifieraient les dividendes futurs.", true, "Ces variations excessives suggèrent des phases d’euphorie et de panique, d’où son analyse des bulles."],
      ["L’aversion aux pertes pousse souvent les investisseurs à vendre trop vite les titres qui ont perdu de la valeur.", false, "Elle pousse au contraire à <b>garder trop longtemps</b> les titres perdants, pour ne pas « réaliser » la perte, et à vendre trop vite les gagnants : c’est l’effet de disposition."]
    ] },

  { id: "fi2-frais", theme: "finance", niveau: 2, type: "calcul", notion: "aversion-pertes",
    titre: "Le poids des frais sur le long terme", competence: "Mesurer l’effet des frais de gestion sur un placement.",
    gen: () => ({ c: pick([10000, 20000, 50000]), r: pick([4, 5, 6]), f1: pick([1.5, 2]), f2: pick([0.2, 0.3]), n: pick([20, 30]) }),
    enonce: (p) => P(`Vous placez <b>${fmt(p.c)} francs</b> pendant <b>${p.n} ans</b> dans un fonds d’actions qui rapporte <b>${p.r} %</b> par an avant frais.`, `Le fonds A prélève <b>${fmt(p.f1)} %</b> de frais par an, le fonds B, un fonds indiciel, <b>${fmt(p.f2)} %</b>. Calculez la valeur finale dans chacun des fonds (arrondie au franc).`),
    champs: [{ label: "Fonds A", unite: "fr.", tol: 2 }, { label: "Fonds B", unite: "fr.", tol: 2 }],
    reponses: (p) => [Math.round(p.c * Math.pow(1 + (p.r - p.f1) / 100, p.n)), Math.round(p.c * Math.pow(1 + (p.r - p.f2) / 100, p.n))],
    indice: "Rendement net = rendement avant frais − frais. Valeur finale = capital × (1 + rendement net) puissance n.",
    correction: (p) => { const a = p.c * Math.pow(1 + (p.r - p.f1) / 100, p.n), b = p.c * Math.pow(1 + (p.r - p.f2) / 100, p.n); return P(`Fonds A : ${fmt(p.c)} × ${fmt(1 + (p.r - p.f1) / 100, 3)}<sup>${p.n}</sup> ≈ <b>${fmt(Math.round(a))} francs</b>.`, `Fonds B : ${fmt(p.c)} × ${fmt(1 + (p.r - p.f2) / 100, 3)}<sup>${p.n}</sup> ≈ <b>${fmt(Math.round(b))} francs</b>.`, `Une différence de frais de ${fmt(p.f1 - p.f2, 1)} point par an représente ${fmt(Math.round(b - a))} francs au bout de ${p.n} ans, soit ${fmt(100 * (b - a) / b, 0)} % de la valeur finale du fonds B. Des frais en apparence faibles pèsent lourd à long terme, à cause des intérêts composés.`); } },

  { id: "fi2-bourse-epargne", theme: "finance", niveau: 2, type: "redaction", notion: "aversion-pertes",
    titre: "Compte d’épargne ou Bourse ?", competence: "Conseiller un choix de placement de façon argumentée.",
    enonce: P("Léo, 25 ans, vient de terminer son apprentissage. Il gagne 5 200 francs par mois et peut épargner 400 francs par mois. Il se demande s’il doit laisser cet argent sur un compte d’épargne ou l’investir en Bourse.", "<b>Consigne :</b> conseillez Léo. Distinguez l’argent dont il peut avoir besoin rapidement et l’épargne de long terme, présentez les avantages et les risques de chaque solution en vous appuyant sur la relation entre risque et rendement, sur la diversification et sur au moins une autre notion (intérêts composés, inflation, frais, pilier 3a), puis terminez par un conseil. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse distingue l’épargne de précaution (disponible rapidement, sans risque) et l’épargne de long terme.", "Elle explique la relation entre risque et rendement, et l’importance de l’horizon de placement.", "Elle mentionne la diversification (fonds indiciel, nombreux titres) plutôt qu’une seule action.", "Elle évoque au moins un autre élément : frais, intérêts composés, inflation qui érode l’épargne, pilier 3a, versements réguliers…", "Elle se termine par un conseil explicite, justifié par au moins un des arguments présentés."],
    corrige: P("Léo devrait d’abord constituer une <b>épargne de précaution</b> sur un compte, équivalant à quelques mois de dépenses, pour faire face aux imprévus sans devoir vendre des placements au mauvais moment.", "Pour l’argent dont il n’aura pas besoin avant de nombreuses années, la Bourse peut convenir : à long terme, les actions ont historiquement rapporté davantage qu’un compte d’épargne, dont le rendement est souvent inférieur à l’<b>inflation</b>. Mais il doit accepter des baisses temporaires importantes : c’est la contrepartie du rendement plus élevé (<b>relation risque-rendement</b>).", "Il devrait <b>diversifier</b>, par exemple avec un fonds indiciel à bas frais, plutôt que miser sur quelques actions, et investir régulièrement chaque mois. Les <b>intérêts composés</b> et des frais faibles jouent fortement sur quarante ans. Il peut aussi utiliser le pilier 3a, qui offre un avantage fiscal, en sachant que l’argent est bloqué jusqu’à la retraite, sauf exceptions.") },

  { id: "fi2-panique", theme: "finance", niveau: 2, type: "qcm", notion: "preteur-dernier-ressort",
    titre: "Arrêter une panique bancaire", competence: "Connaître les outils qui préviennent les paniques bancaires.",
    enonce: P("En 2023, des clients retirent massivement leurs dépôts de Credit Suisse. Quels outils permettent, en général, d’éviter qu’une panique bancaire ne se propage ?"),
    options: ["Une hausse des taux d’intérêt versés sur les dépôts, qui incite les clients à laisser leur argent.", "La garantie des dépôts, qui rassure les petits déposants, et les prêts de la banque centrale aux banques à court de liquidités.", "La suspension des retraits pendant quelques semaines, le temps que la banque vende ses actifs.", "La publication quotidienne des comptes de chaque banque, pour que les déposants jugent eux-mêmes."], c: 1, pourquoi: ["Un taux plus élevé ne rassure pas un déposant qui craint de tout perdre. Seule la certitude d’être remboursé arrête la course aux guichets.", null, "Bloquer les retraits détruit la confiance et pousse les clients des autres banques à retirer leur argent tant qu’ils le peuvent.", "La transparence aide en temps normal. En pleine panique, chacun retire son argent parce qu’il craint que les autres le fassent, même si la banque est solide."],
    explication: P("La <b>garantie des dépôts</b> enlève aux petits déposants la raison de se précipiter au guichet. Le <b>prêteur en dernier ressort</b>, la banque centrale, prête largement aux banques solvables qui manquent temporairement de liquidités, contre de bonnes garanties et à un taux élevé, comme le recommandait Walter Bagehot en 1873.", "Ces outils ont un coût : ils peuvent encourager les banques à prendre trop de risques (<b>aléa moral</b>). Dans le cas de Credit Suisse, les liquidités de la BNS et les garanties de la Confédération ont accompagné une reprise forcée par UBS, en mars 2023.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "fi3-gordon", theme: "finance", niveau: 3, type: "calcul", notion: "instabilite-financiere",
    titre: "La valeur d’une action (modèle de Gordon)", competence: "Évaluer une action à partir de ses dividendes futurs.",
    gen: () => ({ d: pick([2, 3, 4, 5]), r: pick([6, 7, 8, 9]), g: pick([1, 2, 3]), g2: pick([4, 5]) }),
    enonce: (p) => P(`Une entreprise versera l’an prochain un dividende de <b>${p.d} francs</b> par action. On s’attend à ce que ce dividende croisse de <b>${p.g} %</b> par an pour toujours. Les investisseurs exigent un rendement de <b>${p.r} %</b>.`, `Selon le modèle de Gordon, <b>P = D ÷ (r − g)</b>. Calculez le prix de l’action, puis le prix si les investisseurs s’attendaient à une croissance de <b>${p.g2} %</b>. Arrondissez à deux décimales, soit au centime.`),
    champs: [{ label: "Prix", unite: "fr.", tol: 0.05 }, { label: "Prix avec plus de croissance", unite: "fr.", tol: 0.05 }],
    reponses: (p) => [Math.round((p.d / ((p.r - p.g) / 100)) * 100) / 100, Math.round((p.d / ((p.r - p.g2) / 100)) * 100) / 100],
    indice: "Exprimez r et g en fraction avant de soustraire (8 % = 0,08).",
    correction: (p) => { const a = p.d / ((p.r - p.g) / 100), b = p.d / ((p.r - p.g2) / 100); return P(`P = ${p.d} ÷ (${fmt(p.r / 100, 2)} − ${fmt(p.g / 100, 2)}) = <b>${fmt(a)} francs</b>.`, `Avec ${p.g2} % de croissance : P = ${p.d} ÷ (${fmt(p.r / 100, 2)} − ${fmt(p.g2 / 100, 2)}) = <b>${fmt(b)} francs</b>.`, `Une petite révision des anticipations de croissance fait varier le prix de ${fmt(100 * (b / a - 1), 0)} %. C’est pourquoi les cours des actions, surtout celles d’entreprises de croissance, réagissent si fortement aux nouvelles et aux changements d’humeur des marchés, et pourquoi des anticipations trop optimistes peuvent nourrir des bulles.`); } },

  { id: "fi3-hypotheque", theme: "finance", niveau: 3, type: "calcul",
    titre: "Peut-on acheter ce logement ?", competence: "Appliquer les règles suisses de financement d’un logement (version simplifiée).",
    gen: () => ({ prix: rnd(6, 16) * 100000 }),
    enonce: (p) => P("Règles usuelles en Suisse (version simplifiée) : au moins <b>20 %</b> de fonds propres ; les charges annuelles théoriques, calculées avec un taux d’intérêt de <b>5 %</b> sur l’hypothèque, plus <b>1 %</b> d’amortissement de l’hypothèque et <b>1 %</b> du prix pour l’entretien, ne doivent pas dépasser <b>un tiers</b> du revenu brut.", `Un couple veut acheter un appartement à <b>${fmt(p.prix)} francs</b>, avec juste les fonds propres minimaux. Calculez ces fonds propres, puis le revenu brut annuel minimal nécessaire.`),
    champs: [{ label: "Fonds propres", unite: "fr.", tol: 1 }, { label: "Revenu minimal", unite: "fr./an", tol: 3 }],
    reponses: (p) => { const h = 0.8 * p.prix, ch = 0.05 * h + 0.01 * h + 0.01 * p.prix; return [0.2 * p.prix, Math.round(3 * ch)]; },
    indice: "Commencez par le montant de l’hypothèque. Une partie des charges se calcule sur l’hypothèque, l’autre sur le prix.",
    correction: (p) => { const h = 0.8 * p.prix, ch = 0.06 * h + 0.01 * p.prix; return P(`Fonds propres : 20 % × ${fmt(p.prix)} = <b>${fmt(0.2 * p.prix)} francs</b> ; hypothèque : ${fmt(h)} francs.`, `Charges théoriques : 5 % × ${fmt(h)} + 1 % × ${fmt(h)} + 1 % × ${fmt(p.prix)} = ${fmt(0.05 * h)} + ${fmt(0.01 * h)} + ${fmt(0.01 * p.prix)} = ${fmt(ch)} francs par an.`, `Revenu brut minimal : 3 × ${fmt(ch)} = <b>${fmt(Math.round(3 * ch))} francs</b> par an.`, "La moitié au moins des fonds propres exigés, soit 10 % du prix, ne doit pas provenir du 2e pilier. L’amortissement doit ramener la dette aux deux tiers de la valeur du logement en quinze ans.", "Le taux théorique de 5 % est bien supérieur aux taux réels des dernières années : il sert à vérifier que les ménages pourront payer si les taux remontent, et à éviter une bulle immobilière alimentée par le crédit, comme celle des années 1980 en Suisse. Ces règles de prudence sont fixées par les banques et leur autorégulation, sous l’œil de la FINMA."); } },

  { id: "fi3-capm", theme: "finance", niveau: 3, type: "calcul",
    titre: "Le rendement exigé d’une action (MEDAF)", competence: "Appliquer le modèle d’équilibre des actifs financiers.",
    gen: () => ({ rf: pick([0.5, 1, 2]), rm: pick([6, 7, 8]), b: pick([0.5, 0.8, 1, 1.2, 1.5, 2]) }),
    enonce: (p) => P(`Selon le modèle d’équilibre des actifs financiers (MEDAF), le rendement exigé d’une action est : <b>r = r<sub>f</sub> + β × (r<sub>m</sub> − r<sub>f</sub>)</b>, où r<sub>f</sub> est le taux sans risque (<b>${fmt(p.rf)} %</b>), r<sub>m</sub> le rendement attendu du marché (<b>${p.rm} %</b>) et β la sensibilité de l’action aux mouvements du marché.`, `Calculez le rendement exigé d’une action dont le bêta vaut <b>${fmt(p.b, 1)}</b>.`),
    champs: [{ label: "Rendement exigé", unite: "%", tol: 0.01 }],
    reponses: (p) => [Math.round((p.rf + p.b * (p.rm - p.rf)) * 100) / 100],
    indice: "Prime de risque du marché = rm − rf ; multipliez-la par β puis ajoutez rf.",
    correction: (p) => { const r = p.rf + p.b * (p.rm - p.rf); return P(`r = ${fmt(p.rf)} + ${fmt(p.b, 1)} × (${p.rm} − ${fmt(p.rf)}) = ${fmt(p.rf)} + ${fmt(p.b * (p.rm - p.rf), 2)}`, `r = <b>${fmt(r, 2)} %</b>.`, p.b > 1 ? "Le bêta est supérieur à 1 : l’action amplifie les mouvements du marché, elle est plus risquée, et les investisseurs exigent un rendement plus élevé." : p.b < 1 ? "Le bêta est inférieur à 1 : l’action réagit moins que le marché, comme souvent les entreprises de biens de première nécessité, et le rendement exigé est plus faible." : "Avec un bêta de 1, l’action suit le marché, et son rendement exigé est celui du marché.", "Selon le MEDAF, seul le risque lié au marché est rémunéré, car le risque propre à chaque entreprise peut être éliminé par la diversification. Le modèle, dû à William Sharpe (Nobel 1990), reste très utilisé malgré ses limites empiriques."); } },

  { id: "fi3-minsky", theme: "finance", niveau: 3, type: "qcm", notion: "instabilite-financiere",
    titre: "Les trois financements de Minsky", competence: "Classer des emprunteurs selon Minsky.",
    enonce: P("Pendant un boom immobilier, un ménage achète un appartement avec un prêt dont il ne peut payer que les intérêts avec son salaire, en comptant sur la hausse des prix pour revendre avec profit ou refinancer son prêt. Comment Hyman Minsky qualifierait-il ce financement ?"),
    options: ["Un financement prudent (hedge) : les revenus couvrent intérêts et remboursement.", "Un financement spéculatif : les revenus couvrent les intérêts mais pas le remboursement, qui dépend d’un refinancement ou d’une revente.", "Un financement Ponzi : les revenus ne couvrent même pas les intérêts.", "Un financement public."], c: 1, pourquoi: ["Le salaire couvre seulement les intérêts : le remboursement dépend de la revente ou d’un nouveau prêt, ce n’est donc pas prudent.", null, "Le ménage peut payer les intérêts avec son salaire : il n’est pas encore dans la position Ponzi.", "Il s’agit d’un emprunt privé auprès d’une banque, pas d’un financement par l’État."],
    explication: P("Minsky distingue trois positions. <b>Prudente</b> : les revenus couvrent intérêts et capital. <b>Spéculative</b> : ils couvrent les intérêts, mais le remboursement dépend d’un nouveau crédit ou d’une revente. <b>Ponzi</b> : ils ne couvrent même pas les intérêts, et tout repose sur la hausse des prix.", "Selon lui, les périodes de calme font glisser l’économie vers les positions spéculatives et Ponzi : « la stabilité est déstabilisante ». Quand les prix cessent de monter, ces emprunteurs doivent vendre, ce qui peut provoquer un effondrement, comme lors de la crise des subprimes.") },

  { id: "fi3-vf-crises", theme: "finance", niveau: 3, type: "vf", notion: "alea-moral",
    titre: "Crises bancaires et régulation", competence: "Connaître les grandes crises et les réponses réglementaires.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["En octobre 2008, la Confédération et la BNS ont soutenu UBS, fragilisée par ses pertes sur les crédits hypothécaires américains.", true, "La Confédération a apporté 6 milliards de francs et la BNS a repris des actifs toxiques dans un fonds spécial."],
      ["En mars 2023, Credit Suisse a été reprise par UBS, avec le soutien de la Confédération et de la BNS.", true, "La reprise a été organisée en un week-end pour éviter une faillite désordonnée."],
      ["Les accords de Bâle III, adoptés après 2008, ont réduit les exigences de fonds propres des banques.", false, "Ils les ont <b>renforcées</b>, et ont ajouté des exigences de liquidité."],
      ["La disparition de Credit Suisse a mis fin au débat sur les banques « trop grandes pour faire faillite » en Suisse.", false, "Elle l’a relancé. Au moment de la reprise, le bilan d’UBS approchait le double du PIB suisse, et le Conseil fédéral a proposé en 2025 de renforcer fortement ses exigences de fonds propres, projet que le Parlement examine depuis 2026."]
    ] },

  { id: "fi3-diversification-calc", theme: "finance", niveau: 3, type: "calcul", notion: "aversion-pertes",
    titre: "Le calcul de la diversification", competence: "Calculer le risque d’un portefeuille diversifié.",
    gen: () => ({ s: pick([20, 25, 30, 40]), n: pick([4, 9, 16, 25, 100]) }),
    enonce: (p) => P(`Chaque action d’un groupe a un risque (écart-type du rendement annuel) de <b>${p.s} %</b>. On suppose, pour simplifier, que leurs rendements sont indépendants les uns des autres.`, `Vous répartissez votre placement à parts égales entre <b>${p.n} actions</b>. Le risque du portefeuille vaut alors <b>σ ÷ √n</b>. Calculez-le (arrondi à une décimale).`),
    champs: [{ label: "Risque du portefeuille", unite: "%", tol: 0.1 }],
    reponses: (p) => [Math.round((p.s / Math.sqrt(p.n)) * 10) / 10],
    indice: "Calculez d’abord la racine carrée du nombre d’actions.",
    correction: (p) => P(`Risque = ${p.s} ÷ √${p.n} = ${p.s} ÷ ${fmt(Math.sqrt(p.n), 2)}`, `≈ <b>${fmt(p.s / Math.sqrt(p.n), 1)} %</b>.`, "En réalité, les actions ne sont pas indépendantes : elles baissent souvent ensemble lors des crises. La diversification élimine le risque propre à chaque entreprise, mais pas le risque commun au marché. C’est pourquoi le risque d’un portefeuille très diversifié ne descend pas vers zéro, mais vers celui du marché dans son ensemble.") },

  { id: "fi3-ubs", theme: "finance", niveau: 3, type: "redaction", notion: "alea-moral",
    titre: "Faut-il imposer davantage de fonds propres à UBS ?", competence: "Argumenter sur une question de régulation financière.",
    enonce: P("Après la reprise de Credit Suisse, UBS est la seule grande banque internationale de Suisse. Son bilan, proche du double du PIB du pays au moment de la reprise, en représente encore environ une fois et demie. En 2025, le Conseil fédéral a proposé d’exiger qu’elle couvre entièrement par des fonds propres la valeur de ses filiales étrangères, soit de l’ordre de 20 milliards de dollars supplémentaires selon les estimations. Le Parlement examine le projet depuis 2026. UBS juge ces exigences excessives.", "<b>Consigne :</b> faut-il imposer à UBS des exigences de fonds propres nettement plus élevées ? Présentez les arguments des deux côtés, en utilisant au moins deux notions de finance, puis concluez. Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse présente au moins deux arguments pour : stabilité financière, réduction du risque pour les contribuables, aléa moral et garantie implicite de l’État, effet de levier, leçons de 2008 et 2023…", "Elle présente au moins deux arguments contre : coût du capital, compétitivité internationale de la banque, risque de délocalisation, effet sur le crédit et la place financière, comparaison avec les concurrents…", "Elle utilise correctement au moins deux notions : fonds propres, effet de levier, aléa moral, « trop grande pour faire faillite », prêteur en dernier ressort…", "Elle mentionne la taille de la banque par rapport à l’économie suisse et le risque pour les finances publiques.", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("<b>Pour :</b> avec un bilan qui représente environ une fois et demie le PIB suisse, une faillite d’UBS dépasserait les capacités de la Confédération. La banque bénéficie donc d’une garantie implicite de l’État, ce qui crée un <b>aléa moral</b> : elle peut prendre plus de risques en sachant qu’elle sera sauvée. Davantage de <b>fonds propres</b> réduit l’<b>effet de levier</b> : les actionnaires, et non les contribuables, absorbent les pertes. Les crises de 2008 et de 2023 ont montré que les règles précédentes ne suffisaient pas, et des économistes comme Anat Admati et Martin Hellwig plaident pour des fonds propres beaucoup plus élevés.", "<b>Contre :</b> pour la banque, les fonds propres sont un financement plus coûteux que la dette, notamment parce que les intérêts sont déductibles et que la dette profite de la garantie implicite de l’État. Admati et Hellwig répondent que ce surcoût est privé et non social. Une banque mieux capitalisée est moins risquée, et ses actionnaires peuvent se contenter d’un rendement plus faible. Des exigences très supérieures à celles des concurrents étrangers pourraient néanmoins réduire la rentabilité et la compétitivité d’UBS, l’inciter à réduire certaines activités ou à déplacer son siège, et affaiblir la place financière suisse.", "<b>Conclusion :</b> au vu de la taille d’UBS par rapport à l’économie suisse, des exigences plus élevées semblent justifiées pour protéger les contribuables, mais leur ampleur et leur calendrier doivent tenir compte de la compétitivité de la banque. Le débat porte moins sur le principe que sur le niveau.") },

  { id: "fi3-bulle", theme: "finance", niveau: 3, type: "document", notion: "instabilite-financiere",
    titre: "Reconnaître une bulle", competence: "Appliquer l’anatomie des crises de Kindleberger à des données.",
    enonce: P("Évolution d’un indice fictif des prix d’un actif (base 100) et du crédit accordé pour l’acheter :") +
      `<table><thead><tr><th>Année</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th></tr></thead><tbody><tr><td>Prix</td><td>100</td><td>112</td><td>132</td><td>165</td><td>240</td><td>238</td><td>150</td></tr><tr><td>Crédit (base 100)</td><td>100</td><td>110</td><td>128</td><td>160</td><td>230</td><td>235</td><td>190</td></tr></tbody></table>` +
      P("Quelle lecture correspond le mieux à l’anatomie des crises de Kindleberger et Minsky ?"),
    options: ["Une hausse régulière fondée sur les revenus de l’actif, suivie d’une correction normale.", "Essor nourri par le crédit (années 2 à 4), euphorie (année 5), retournement (année 6), puis panique (année 7).", "Une baisse continue des prix dès la première année, qui entraîne ensuite celle du crédit.", "Un marché sans lien avec le crédit, dont les prix évoluent indépendamment de l’endettement."], c: 1,
    pourquoi: ["De l’année 1 à l’année 5, les prix sont multipliés par 2,4 et le crédit par 2,3, puis les prix chutent de 37 % en un an. Une hausse fondée sur les revenus attendus ne s’accompagne ni d’un tel emballement du crédit ni d’un tel effondrement.", null, "Les prix montent de 100 à 240 pendant cinq ans avant de baisser.", "Le crédit et les prix montent presque du même pas, de 100 à 230 et de 100 à 240, puis reculent ensemble."],
    explication: P("Le schéma correspond aux phases décrites par Kindleberger : <b>essor</b>, où le crédit et les prix montent ensemble ; <b>euphorie</b>, où les prix accélèrent, avec une hausse de 45 % en une année ; <b>retournement</b>, quand les prix cessent de monter alors que l’endettement est au plus haut ; puis <b>panique</b>, où les emprunteurs doivent vendre, ce qui fait chuter les prix de 37 %.", "Le crédit joue un rôle central : il alimente la hausse, puis rend la chute plus brutale, car les emprunteurs endettés sont forcés de vendre. On retrouve ce schéma de la crise de John Law en 1720 aux subprimes en 2008.") },
  { id: "fi1-fait-valeur", theme: "finance", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat ou jugement de valeur ?", competence: "Distinguer un constat, que l’on peut vérifier, d’un jugement de valeur, qui dit ce qui devrait être.",
    enonce: P("Pour chaque affirmation, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b>, qui dit ce qui devrait être."),
    affirmations: [
      ["Les frais prélevés par les fonds de placement sont trop élevés.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : « trop élevés » est une appréciation, qui dépend de ce que l’on juge acceptable."],
      ["Sur longue période, les actions ont rapporté en moyenne davantage que les comptes d’épargne.", true, "On peut le vérifier avec des données : les séries historiques de rendement le montrent."],
      ["Un fonds qui prélève 2 % de frais par an devrait rapporter moins, après frais, qu’un fonds identique qui en prélève 0,2 %.", true, "On peut le vérifier avec des données : à rendement avant frais égal, le rendement net est plus faible quand les frais sont plus élevés. Ici, « devrait » exprime une attente, pas un souhait."],
      ["Spéculer en Bourse est immoral.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : « immoral » est une appréciation morale."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "fi1-credit", theme: "finance", niveau: 1, type: "calcul",
    titre: "Ce que coûte un achat à crédit", competence: "Calculer le coût total d’un crédit à partir des mensualités.",
    gen: () => { const prix = rnd(15, 40) * 1000, n = pick([36, 48, 60]); return { prix, n, m: Math.round(prix * (1 + pick([8, 10, 12, 15]) / 100) / n) }; },
    enonce: (p) => P(`Une voiture coûte <b>${fmt(p.prix)} francs</b> au comptant. Le vendeur propose de la payer en <b>${p.n} mensualités</b> de <b>${fmt(p.m)} francs</b>.`, "Combien l’acheteur paie-t-il en plus s’il choisit le crédit ?"),
    champs: [{ label: "Coût du crédit", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [p.m * p.n - p.prix],
    indice: "Calculez d’abord le total des mensualités, puis comparez-le au prix au comptant.",
    correction: (p) => P(`Total des mensualités : ${p.n} × ${fmt(p.m)} = ${fmt(p.m * p.n)} francs.`, `Coût du crédit = ${fmt(p.m * p.n)} − ${fmt(p.prix)} = <b>${fmt(p.m * p.n - p.prix)} francs</b>.`, "Ce supplément rémunère le prêteur, qui avance l’argent et court le risque de ne pas être remboursé. Une mensualité qui paraît modeste peut cacher un coût total élevé. C’est pourquoi la loi oblige à indiquer le taux annuel effectif d’un crédit.") },

  { id: "fi1-graph-risque", theme: "finance", niveau: 1, type: "graphique", notion: "aversion-pertes",
    titre: "Rendement et risque de deux placements", competence: "Comparer le rendement moyen et la régularité de deux placements sur un graphique.",
    enonce: P("Le graphique donne le rendement annuel de deux placements pendant six ans : un compte d’épargne et un fonds en actions.", "Que montre-t-il ?"),
    fig: () => X.barres({ cats: ["1", "2", "3", "4", "5", "6"], vals: [1, 1, 1, 1, 1, 1], vals2: [12, -18, 20, 7, -5, 14], noms: ["Compte d’épargne", "Fonds en actions"], ymin: -24, ymax: 26, unite: "", dec: 0, aria: "Rendements annuels d’un compte d’épargne, toujours 1 pour cent, et d’un fonds en actions, très variables", caption: "Rendement annuel en %, années 1 à 6. Données inventées pour l’exercice." }),
    options: ["Le fonds rapporte en moyenne 5 % par an contre 1 %, mais son rendement varie beaucoup et peut être négatif.", "Le fonds rapporte davantage que le compte d’épargne chacune des six années.", "Le compte d’épargne rapporte davantage sur les six ans, puisqu’il ne perd jamais de valeur.", "Les deux placements présentent le même risque, puisque leur rendement moyen est positif."], c: 0,
    pourquoi: [null, "Les années 2 et 5, le fonds perd 18 % puis 5 %, alors que le compte rapporte 1 %.", "Ne jamais perdre ne suffit pas à rapporter plus. La moyenne des rendements du fonds est de 5 % par an, contre 1 % pour le compte.", "Le risque ne se lit pas sur la moyenne, mais sur les écarts autour d’elle. Le rendement du compte ne varie pas, celui du fonds va de −18 % à +20 %."],
    explication: P("Rendement moyen du fonds : (12 − 18 + 20 + 7 − 5 + 14) ÷ 6 = <b>5 %</b> par an. Celui du compte est de <b>1 %</b>.", "Le fonds rapporte plus en moyenne, mais de façon très irrégulière. C’est la relation entre <b>rendement et risque</b>. Un placement qui rapporte plus en moyenne expose à des pertes certaines années.", "Ce risque pèse surtout sur l’argent dont on aura besoin bientôt. Celui qui doit vendre à la fin de l’année 2 subit la perte de 18 %. Sur une longue durée, les bonnes années ont le temps de compenser les mauvaises.") },

  { id: "fi1-rente", theme: "finance", niveau: 1, type: "calcul",
    titre: "De l’avoir de vieillesse à la rente", competence: "Calculer une rente annuelle à partir d’un capital et d’un taux de conversion.",
    gen: () => ({ avoir: rnd(25, 60) * 10000 }),
    enonce: (p) => P(`À la retraite, une salariée a accumulé <b>${fmt(p.avoir)} francs</b> dans sa caisse de pension (2e pilier, part obligatoire). La caisse transforme ce capital en rente à l’aide du taux de conversion légal de <b>6,8 %</b>.`, "Quelle rente annuelle recevra-t-elle ?"),
    champs: [{ label: "Rente annuelle", unite: "fr.", tol: 0.5 }],
    reponses: (p) => [p.avoir * 0.068],
    indice: "Le taux de conversion s’applique au capital accumulé et donne la rente d’une année.",
    correction: (p) => P(`Rente annuelle = ${fmt(p.avoir)} × 6,8 ÷ 100`, `= <b>${fmt(p.avoir * 0.068)} francs</b> par an, soit ${fmt(p.avoir * 0.068 / 12, 0)} francs par mois.`, "Cette rente s’ajoute à celle de l’AVS (1er pilier). Avec un taux de 6,8 %, le capital est épuisé en moins de quinze ans s’il ne rapporte rien. Comme l’espérance de vie à 65 ans dépasse vingt ans, la caisse doit compter sur le rendement de ses placements, ce qui alimente le débat sur le niveau de ce taux.") },

  /* ----- Niveau 2 ----- */
  { id: "fi2-van", theme: "finance", niveau: 2, type: "calcul",
    titre: "Faut-il acheter cette machine ?", competence: "Calculer un délai de récupération et une valeur actuelle nette.",
    gen: () => { const I = pick([80, 100, 120, 150]) * 1000; return { I, F: Math.round(I * pick([0.25, 0.28, 0.3, 0.32]) / 1000) * 1000, r: pick([5, 6, 8]) }; },
    enonce: (p) => P(`Une entreprise envisage d’acheter une machine <b>${fmt(p.I)} francs</b>. Elle lui rapporterait <b>${fmt(p.F)} francs</b> nets à la fin de chacune des <b>cinq</b> années suivantes, puis ne vaudrait plus rien. Le taux d’actualisation retenu est de <b>${p.r} %</b>.`, "Calculez le délai de récupération de l’investissement (en années, deux décimales), puis la valeur actuelle nette du projet, arrondie au franc. Indiquez un signe moins si elle est négative."),
    champs: [{ label: "Délai de récupération", unite: "années", tol: 0.01 }, { label: "Valeur actuelle nette", unite: "fr.", tol: 60 }],
    reponses: (p) => { const r = p.r / 100; let v = -p.I; for (let t = 1; t <= 5; t++) v += p.F / Math.pow(1 + r, t); return [Math.round(p.I / p.F * 100) / 100, Math.round(v)]; },
    indice: "Le délai de récupération ne tient pas compte du temps. Pour la valeur actuelle nette, divisez chaque rentrée par (1 + taux) élevé à la puissance du nombre d’années, additionnez, puis retranchez le prix d’achat.",
    correction: (p) => { const r = p.r / 100, vals = [1, 2, 3, 4, 5].map((t) => p.F / Math.pow(1 + r, t)), s = vals.reduce((a, b) => a + b, 0); return P(`Délai de récupération = ${fmt(p.I)} ÷ ${fmt(p.F)}`, `≈ <b>${fmt(p.I / p.F, 2)} années</b>.`, `Valeurs actuelles des cinq rentrées, à ${p.r} % : ${vals.map((v) => fmt(v, 0)).join(", ")} francs. Leur somme vaut ${fmt(s, 0)} francs.`, `Valeur actuelle nette = ${fmt(s, 0)} − ${fmt(p.I)} ≈ <b>${fmt(s - p.I, 0)} francs</b>.`, s - p.I > 0 ? "La valeur actuelle nette est positive. La machine rapporte plus que ce que le même argent rapporterait ailleurs au taux retenu. Le projet crée de la valeur." : "La valeur actuelle nette est négative. Les rentrées ne compensent pas l’argent immobilisé au taux retenu, alors même que le prix d’achat est récupéré avant cinq ans. Le projet est à écarter.", "Le délai de récupération est simple, mais il ignore la valeur du temps et tout ce qui se passe après le remboursement. La valeur actuelle nette est le critère le plus sûr."); } },

  { id: "fi2-doc-bilan", theme: "finance", niveau: 2, type: "document",
    titre: "Lire le bilan d’une entreprise", competence: "Tirer d’un bilan le degré d’autofinancement et la capacité à payer les dettes à court terme.",
    enonce: P("Voici le bilan simplifié d’une entreprise, en milliers de francs.") +
      `<table><thead><tr><th>Actifs</th><th></th><th>Passifs</th><th></th></tr></thead><tbody><tr><td>Liquidités</td><td>80</td><td>Dettes à court terme</td><td>250</td></tr><tr><td>Créances sur les clients</td><td>220</td><td>Dettes à long terme</td><td>350</td></tr><tr><td>Stocks</td><td>200</td><td>Fonds propres</td><td>400</td></tr><tr><td>Machines et bâtiments</td><td>500</td><td></td><td></td></tr><tr><th>Total</th><th>1 000</th><th>Total</th><th>1 000</th></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Les fonds propres financent 40 % du bilan, et les liquidités et les créances dépassent les dettes à court terme.", "Les fonds propres, 400 000 francs, sont l’argent dont l’entreprise dispose sur ses comptes.", "L’entreprise est en faillite, puisque ses dettes dépassent ses fonds propres de 200 000 francs.", "L’entreprise ne peut pas payer ses dettes à court terme, puisqu’elle n’a que 80 000 francs de liquidités."], c: 0,
    pourquoi: [null, "Les fonds propres figurent au passif. Ils disent d’où vient l’argent, celui des propriétaires, et non où il se trouve. L’argent disponible est le poste « Liquidités », à l’actif.", "Une entreprise est en difficulté quand ses dettes dépassent ses actifs, pas ses fonds propres. Ici les actifs valent 1 000 et les dettes 600. Beaucoup d’entreprises saines ont plus de dettes que de fonds propres.", "Les créances sur les clients seront encaissées dans les semaines qui viennent. Avec les liquidités, elles représentent 300 000 francs, plus que les 250 000 francs de dettes à court terme."],
    explication: P("Le <b>passif</b> indique l’origine des fonds, l’<b>actif</b> leur emploi. Les deux totaux sont toujours égaux.", "Part des fonds propres : 400 ÷ 1 000 = <b>40 %</b>. Plus elle est élevée, plus l’entreprise peut absorber des pertes sans mettre ses créanciers en danger.", "Capacité à payer à court terme : (80 + 220) ÷ 250 = <b>120 %</b>. Les liquidités et les créances couvrent les dettes qui arrivent à échéance. Les stocks n’entrent pas dans ce calcul, car il n’est pas sûr qu’ils se vendent vite.") },

  { id: "fi2-graph-taux", theme: "finance", niveau: 2, type: "graphique", notion: "preference-liquidite",
    titre: "La courbe des taux", competence: "Interpréter la forme d’une courbe des taux.",
    enonce: P("La courbe des taux donne le rendement des obligations d’un État selon leur échéance. Le graphique en montre deux, relevées à deux dates différentes.", "Que signale la courbe inversée ?"),
    fig: () => X.graphe({ xmax: 10.8, ymax: 4.6, ylab: "Rendement (%)", xlab: "Échéance (années)", aria: "Deux courbes des taux, l’une croissante, l’autre décroissante",
      gx: [[2, "2"], [5, "5"], [10, "10"]], gy: [[1, "1"], [2, "2"], [3, "3"], [4, "4"]],
      lignes: [{ f: (t) => 1 + 1.6 * (1 - Math.exp(-t / 3)), de: 0.25, a: 10, col: "d", lab: "courbe normale", at: [10, 2.54], dy: 22, anc: "end" }, { f: (t) => 3.8 - 1.5 * (1 - Math.exp(-t / 3)), de: 0.25, a: 10, col: "r", dash: true, lab: "courbe inversée", at: [10, 2.35], dx: -150, dy: -34, anc: "end" }],
      caption: "Schéma construit pour l’exercice." }),
    options: ["Les investisseurs s’attendent à une baisse des taux courts, souvent liée à un ralentissement de l’économie.", "Les investisseurs s’attendent à une hausse de l’inflation et des taux courts dans les années à venir.", "Les obligations à dix ans sont devenues moins risquées que les obligations à un an.", "L’État paie désormais plus cher ses emprunts à dix ans que ses emprunts à un an."], c: 0,
    pourquoi: [null, "Si les taux courts devaient monter, les investisseurs exigeraient davantage pour s’engager sur dix ans. La courbe serait croissante, et plus raide encore.", "Une obligation longue reste plus sensible aux variations de taux. Si elle rapporte moins, c’est parce qu’on attend des taux courts plus bas à l’avenir.", "C’est l’inverse sur la courbe inversée. Le rendement à dix ans y est inférieur au rendement à un an."],
    explication: P("Un taux à dix ans reflète la moyenne des taux courts attendus pendant dix ans, augmentée d’une prime pour l’immobilisation de l’argent. En temps normal, la courbe est donc <b>croissante</b>.", "Elle s’<b>inverse</b> quand la banque centrale a fortement relevé ses taux courts et que les investisseurs s’attendent à les voir redescendre. Ils prévoient en général que l’activité et l’inflation vont ralentir.", "Aux États-Unis, la plupart des récessions depuis les années 1960 ont été précédées d’une inversion. Le signal n’est pas infaillible. La courbe s’est inversée en 2022 sans qu’une récession suive dans les deux années suivantes.") },

  { id: "fi2-rationnement", theme: "finance", niveau: 2, type: "qcm", notion: "asymetrie-information",
    titre: "Pourquoi un taux plus élevé peut coûter à la banque", competence: "Appliquer la sélection adverse au marché du crédit.",
    enonce: P("Une banque relève fortement le taux de ses prêts aux petites entreprises. Elle ne peut pas savoir avec précision lesquels de ses clients ont des projets risqués.", "Pourquoi cette hausse peut-elle réduire son bénéfice au lieu de l’augmenter ?"),
    options: ["Les emprunteurs prudents renoncent, et il reste surtout ceux dont les projets sont les plus risqués.", "Les emprunteurs remboursent plus vite pour payer moins d’intérêts, ce qui réduit les recettes.", "Les déposants exigent aussitôt un taux plus élevé sur leur épargne, ce qui annule le gain.", "La banque centrale relève à son tour son taux directeur, ce qui renchérit le refinancement."], c: 0,
    pourquoi: [null, "Un remboursement anticipé réduit un peu les intérêts encaissés, mais il ne fait pas perdre le capital. Le danger vient des clients qui ne rembourseront pas.", "Le taux servi aux déposants dépend du marché de l’épargne, pas du taux d’un type de prêt. Rien n’oblige la banque à le relever.", "Le taux directeur dépend de l’inflation et de la conjoncture, pas de la politique commerciale d’une banque."],
    explication: P("C’est un cas de <b>sélection adverse</b>. L’emprunteur connaît mieux son projet que la banque. À un taux élevé, seuls restent ceux qui espèrent un gain très fort, donc incertain, ou ceux qui savent qu’ils risquent de ne pas rembourser.", "La qualité moyenne des emprunteurs se dégrade, et les pertes sur les prêts peuvent dépasser le supplément d’intérêts. La banque préfère alors garder un taux modéré et refuser une partie des demandes. C’est le <b>rationnement du crédit</b>, analysé par Joseph Stiglitz et Andrew Weiss en 1981.", "D’où l’importance des garanties, de l’historique du client et des relations de longue durée, qui réduisent l’écart d’information.") },

  /* ----- Niveau 3 ----- */
  { id: "fi3-cmpc", theme: "finance", niveau: 3, type: "calcul",
    titre: "Le coût du capital d’une entreprise", competence: "Calculer un coût des fonds propres et un coût moyen pondéré du capital, puis juger un projet.",
    gen: () => ({ rf: pick([1, 2]), prime: pick([4, 5, 6]), beta: pick([0.8, 1.2, 1.5]), kd: pick([3, 4]), tax: pick([15, 20, 25]), we: pick([40, 50, 60]), tri: pick([5, 6, 7, 8]) }),
    enonce: (p) => P(`Une entreprise se finance à <b>${p.we} %</b> par des fonds propres et à <b>${100 - p.we} %</b> par de la dette. Le taux sans risque est de <b>${p.rf} %</b>, la prime de risque du marché de <b>${p.prime} %</b> et le bêta de l’entreprise de <b>${fmt(p.beta)}</b>. Sa dette lui coûte <b>${p.kd} %</b>, et les intérêts sont déductibles d’un impôt sur le bénéfice de <b>${p.tax} %</b>.`, `Calculez le coût de ses fonds propres selon le modèle d’évaluation des actifs financiers, puis son coût moyen pondéré du capital. Arrondissez à deux décimales. Comparez ensuite ce coût au taux de rendement interne du projet qu’elle étudie, soit ${p.tri} %, pour juger s’il faut l’accepter. La correction donne la décision.`),
    champs: [{ label: "Coût des fonds propres", unite: "%", tol: 0.01 }, { label: "Coût moyen pondéré du capital", unite: "%", tol: 0.01 }],
    reponses: (p) => { const ke = p.rf + p.beta * p.prime; return [Math.round(ke * 100) / 100, Math.round((p.we * ke + (100 - p.we) * p.kd * (1 - p.tax / 100)) / 100 * 100) / 100]; },
    indice: "Le coût des fonds propres ajoute au taux sans risque une prime proportionnelle au bêta. Dans la moyenne pondérée, le coût de la dette se prend après impôt.",
    correction: (p) => { const ke = p.rf + p.beta * p.prime, kd = p.kd * (1 - p.tax / 100), w = (p.we * ke + (100 - p.we) * kd) / 100; return P(`Coût des fonds propres = taux sans risque + bêta × prime de risque = ${p.rf} + ${fmt(p.beta)} × ${p.prime}.`, `Soit <b>${fmt(ke, 2)} %</b>.`, `Coût de la dette après impôt = ${p.kd} × (1 − ${fmt(p.tax / 100)}) = ${fmt(kd, 2)} %.`, `Coût moyen pondéré = ${fmt(p.we / 100)} × ${fmt(ke, 2)} + ${fmt(1 - p.we / 100)} × ${fmt(kd, 2)} ≈ <b>${fmt(w, 2)} %</b>.`, Math.abs(p.tri - w) < 0.005 ? `Le projet rapporte ${p.tri} %, exactement le coût du capital. Il ne crée ni ne détruit de valeur, et l’entreprise est indifférente.` : p.tri > w ? `Le projet rapporte ${p.tri} %, plus que le coût du capital. Il crée de la valeur et doit être accepté.` : `Le projet rapporte ${p.tri} %, pas plus que le coût du capital. Il ne rémunère pas assez ceux qui le financent et doit être écarté.`, "La dette paraît moins chère que les fonds propres. Franco Modigliani et Merton Miller ont pourtant montré en 1958 que, sans impôt ni risque de faillite, la valeur d’une entreprise ne dépend pas de la façon dont elle se finance. Plus de dette rend les fonds propres plus risqués, donc plus coûteux, et les deux effets se compensent. L’avantage de la dette vient de la déduction des intérêts, sa limite du coût des difficultés financières."); } },

  { id: "fi3-obligation", theme: "finance", niveau: 3, type: "calcul",
    titre: "Prix et duration d’une obligation", competence: "Actualiser les flux d’une obligation et mesurer sa sensibilité aux taux.",
    gen: () => { let c, r; do { c = pick([2, 3, 4]); r = pick([1, 3, 5]); } while (c === r); return { c, r }; },
    enonce: (p) => P(`Une obligation de <b>100 francs</b> de valeur nominale verse un coupon annuel de <b>${p.c} %</b> pendant <b>trois ans</b>, puis rembourse le nominal. Le taux du marché pour cette échéance est de <b>${p.r} %</b>.`, "Calculez le prix de l’obligation, sa duration (la moyenne des dates de paiement, pondérée par la valeur actuelle de chaque paiement), puis la variation approximative de son prix, en %, si le taux du marché monte d’un point. Arrondissez à deux décimales et indiquez un signe moins pour une baisse."),
    champs: [{ label: "Prix", unite: "fr.", tol: 0.01 }, { label: "Duration", unite: "années", tol: 0.01 }, { label: "Variation du prix", unite: "%", tol: 0.02 }],
    reponses: (p) => { const r = p.r / 100, f = [p.c, p.c, 100 + p.c].map((x, k) => x / Math.pow(1 + r, k + 1)), P0 = f[0] + f[1] + f[2], D = (f[0] + 2 * f[1] + 3 * f[2]) / P0; return [Math.round(P0 * 100) / 100, Math.round(D * 100) / 100, Math.round(-D / (1 + r) * 100) / 100]; },
    indice: "Actualisez séparément les trois paiements. La sensibilité du prix à une hausse d’un point vaut à peu près la duration divisée par (1 + taux), avec un signe moins.",
    correction: (p) => { const r = p.r / 100, f = [p.c, p.c, 100 + p.c].map((x, k) => x / Math.pow(1 + r, k + 1)), P0 = f[0] + f[1] + f[2], D = (f[0] + 2 * f[1] + 3 * f[2]) / P0; return P(`Valeurs actuelles des paiements : ${p.c} ÷ ${fmt(1 + r, 2)} = ${fmt(f[0], 3)} ; ${p.c} ÷ ${fmt(1 + r, 2)}² = ${fmt(f[1], 3)} ; ${100 + p.c} ÷ ${fmt(1 + r, 2)}³ = ${fmt(f[2], 3)}.`, `Prix = somme des trois valeurs ≈ <b>${fmt(P0, 2)} francs</b>.`, `Duration = (1 × ${fmt(f[0], 3)} + 2 × ${fmt(f[1], 3)} + 3 × ${fmt(f[2], 3)}) ÷ ${fmt(P0, 2)} ≈ <b>${fmt(D, 2)} années</b>.`, `Variation du prix ≈ −${fmt(D, 2)} ÷ ${fmt(1 + r, 2)} ≈ <b>${fmt(-D / (1 + r), 2)} %</b> pour un point de taux en plus.`, p.c > p.r ? "Le coupon dépasse le taux du marché. L’obligation vaut plus que son nominal." : "Le coupon est inférieur au taux du marché. L’obligation vaut moins que son nominal.", "Plus la duration est longue, plus le prix réagit aux taux. C’est ce qui a mis en difficulté en 2023 des banques qui détenaient beaucoup d’obligations longues achetées quand les taux étaient très bas."); } },

  { id: "fi3-graph-frontiere", theme: "finance", niveau: 3, type: "graphique",
    titre: "La frontière efficiente et l’actif sans risque", competence: "Lire le choix de portefeuille sur un graphique de rendement et de risque.",
    enonce: P("La courbe verte réunit les meilleurs portefeuilles d’actions possibles, ceux qui offrent le rendement le plus élevé pour chaque niveau de risque. Un investisseur peut aussi prêter ou emprunter au taux sans risque de 2 %. La droite part de ce taux et touche la courbe au portefeuille T. Les portefeuilles A et B ont le même risque.", "Quelle lecture est correcte ?"),
    fig: () => X.graphe({ xmax: 25, ymax: 12.6, ylab: "Rendement attendu (%)", xlab: "Risque (écart-type, %)", aria: "Frontière efficiente et droite passant par le taux sans risque et le portefeuille tangent",
      gx: [[10, "10"], [17, "17"]], gy: [[2, "2"], [6.3, "6,3"], [8.1, "8,1"], [9.3, "9,3"]], reperes: [[17, 9.31]],
      lignes: [{ pts: [[8, 3], [7, 4], [8, 5.2], [10, 6.3], [13, 7.3], [17, 8.1], [22, 8.7]], col: "d", lab: "frontière efficiente", at: [22, 8.7], dy: 22, anc: "end" }, { pts: [[0, 2], [22, 11.46]], col: "o", lab: "droite de marché", at: [22, 11.46], dx: -8, dy: -8, anc: "end" }],
      points: [{ x: 10, y: 6.3, lab: "T", dx: -8, dy: -10, anc: "end" }, { x: 17, y: 8.1, lab: "A", col: "d", dx: 8, dy: 18 }, { x: 17, y: 9.31, lab: "B", col: "o", dx: -8, dy: -10, anc: "end" }],
      caption: "Schéma construit pour l’exercice." }),
    options: ["B rapporte plus que A pour le même risque, en empruntant pour placer davantage dans le portefeuille T.", "A est préférable à B, car il ne contient que des actions et ne recourt pas à l’emprunt.", "Les portefeuilles de la courbe se valent, puisque plus de rendement y va avec plus de risque.", "Le portefeuille le moins risqué de la courbe est le meilleur choix pour n’importe quel investisseur."], c: 0,
    pourquoi: [null, "À risque égal, A rapporte 8,1 % et B 9,3 %. Un investisseur qui accepte ce risque n’a aucune raison de se contenter de A.", "Les portefeuilles de la courbe ne se valent plus dès qu’on peut prêter ou emprunter. La droite qui passe par T domine tous les autres points de la courbe.", "Le portefeuille le moins risqué convient à un investisseur très prudent. Mais il ferait encore mieux en combinant T et le placement sans risque, sur la droite."],
    explication: P("La droite donne le meilleur rendement pour chaque niveau de risque. Entre le taux sans risque et T, l’investisseur prête une partie de son argent. Au-delà de T, il emprunte pour investir plus que sa mise.", "Le point B s’obtient en plaçant 170 % de sa mise dans T, dont 70 % empruntés à 2 %. Son rendement vaut 1,7 × 6,3 − 0,7 × 2 ≈ <b>9,3 %</b>, contre 8,1 % pour A, avec le même risque de 17 %.", "Tous les investisseurs détiennent donc le même portefeuille d’actions T, et ne diffèrent que par la part qu’ils prêtent ou empruntent. C’est le théorème de séparation de James Tobin (1958), qui prolonge l’analyse de Harry Markowitz et fonde le modèle d’évaluation des actifs financiers de William Sharpe.", "Ce cadre suppose que l’écart-type mesure bien le risque. Benoît Mandelbrot a montré que les variations extrêmes sont bien plus fréquentes que ne le prévoit la loi normale, et la finance comportementale que les investisseurs redoutent davantage une perte qu’ils n’apprécient un gain de même taille.") },

  { id: "fi3-red-efficience", theme: "finance", niveau: 3, type: "redaction", notion: "instabilite-financiere",
    titre: "Les marchés financiers évaluent-ils correctement les actifs ?", competence: "Comparer plusieurs théories des marchés financiers et leurs conséquences pour la régulation.",
    enonce: P("En 2013, le prix dit Nobel d’économie a récompensé notamment Eugene Fama, pour qui les cours reflètent toute l’information disponible, et Robert Shiller, pour qui ils s’en écartent durablement. La question divise toujours les économistes.", "<b>Consigne :</b> comparez au moins trois analyses des marchés financiers en les rattachant à leurs auteurs (efficience chez Fama ; esprits animaux et concours de beauté chez Keynes ; exubérance irrationnelle chez Shiller et finance comportementale ; instabilité financière chez Minsky). Dites pour chacune comment se forment les prix, si les bulles sont possibles et quelle régulation elle inspire. Appuyez-vous sur au moins un épisode historique, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois analyses et nomme leurs auteurs.", "Elle dit pour chacune comment se forment les prix (information, opinion des autres, biais psychologiques, crédit).", "Elle indique pour chacune si les bulles sont possibles et pourquoi.", "Elle associe à chaque analyse une position sur la régulation.", "Elle cite au moins un épisode historique et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Fama.</b> Sur un marché efficient, les cours intègrent aussitôt toute l’information disponible. Personne ne peut battre durablement le marché, sauf par hasard, ce que confirment les faibles performances des gérants actifs après frais. Une bulle ne se reconnaît qu’après coup, et il vaut mieux laisser les prix se former librement.", "<b>Keynes.</b> Sur un marché liquide, chacun cherche moins à estimer la valeur d’une entreprise qu’à deviner ce que les autres en penseront, comme dans un concours où il faut désigner le visage que la majorité préférera. Les cours dépendent de conventions fragiles et des « esprits animaux ». Les bulles y sont donc possibles, puisque les cours peuvent s’éloigner longtemps de la valeur des entreprises. Keynes en concluait qu’il faut décourager la spéculation de court terme.", "<b>Shiller et la finance comportementale.</b> Les cours des actions varient bien plus que les dividendes qu’ils sont censés anticiper. Les investisseurs extrapolent les hausses passées, s’imitent et surestiment leurs connaissances. Les bulles sont possibles et durables, parce que parier contre elles est risqué. La bulle des valeurs Internet, de 1998 à 2000, en est l’exemple type. Shiller en tire un appui à des garde-fous, comme l’information des épargnants et la limitation de l’endettement pour spéculer.", "<b>Minsky.</b> L’instabilité vient du crédit. Une longue période calme pousse emprunteurs et prêteurs à s’endetter davantage, jusqu’au point où les revenus ne couvrent plus les intérêts. Les bulles sont donc possibles et naissent du crédit. La crise des crédits hypothécaires à risque de 2007 et 2008 a suivi ce schéma. Minsky plaide pour une surveillance du crédit et pour un prêteur en dernier ressort.", "<b>Prise de position possible.</b> Les deux constats sont compatibles. Il est très difficile de battre le marché, ce qui donne raison à Fama et justifie les fonds indiciels. Mais des prix imprévisibles ne sont pas forcément des prix justes. Les épisodes de 2000 et de 2008 montrent des écarts durables, amplifiés par le crédit. Une régulation qui limite l’endettement des banques et des emprunteurs paraît mieux fondée qu’une tentative de corriger les cours eux-mêmes.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
